package uk.org.sailing.signal;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.widget.*;import java.io.*;
public class MainActivity extends Activity {
 TextView status;static final String[] PERMS={"android.permission.ACCESS_FINE_LOCATION","android.permission.ACCESS_COARSE_LOCATION","android.permission.READ_PHONE_STATE","android.permission.POST_NOTIFICATIONS"};
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout v=new LinearLayout(this);v.setOrientation(1);v.setPadding(28,40,28,20);TextView title=new TextView(this);title.setText("Sailing-UK Signal Logger\nField test v0.3");title.setTextSize(23);v.addView(title);status=new TextView(this);status.setText("Ready. GPS + cellular sampling every 5 seconds.\nNo uploads. Screen-off logging uses a foreground notification.");status.setTextSize(16);v.addView(status);Button start=new Button(this);start.setText("START SURVEY");v.addView(start);Button stop=new Button(this);stop.setText("STOP SURVEY");v.addView(stop);Button export=new Button(this);export.setText("SHARE LATEST CSV");v.addView(export);setContentView(v);start.setOnClickListener(w->start());stop.setOnClickListener(w->{stopService(new Intent(this,SurveyService.class));status.setText("Survey stopped. Choose Share latest CSV.");});export.setOnClickListener(w->share());}
 void start(){if(checkSelfPermission("android.permission.ACCESS_FINE_LOCATION")!=PackageManager.PERMISSION_GRANTED||checkSelfPermission("android.permission.READ_PHONE_STATE")!=PackageManager.PERMISSION_GRANTED){requestPermissions(PERMS,3);status.setText("Grant requested permissions, then tap START again.");return;}try{startForegroundService(new Intent(this,SurveyService.class));status.setText("Survey started. Check persistent notification.\nKeep the phone outdoors for GPS fix.");}catch(Exception e){status.setText("Start failed: "+e.getMessage());}}
 void share(){File dir=getExternalFilesDir(null);if(dir==null)return;File[] fs=dir.listFiles((d,n)->n.endsWith(".csv"));if(fs==null||fs.length==0){status.setText("No CSV yet");return;}File newest=fs[0];for(File f:fs)if(f.lastModified()>newest.lastModified())newest=f;status.setText("Latest CSV: "+newest.getAbsolutePath()+"\nFor now retrieve with USB/ADB. Secure file sharing is pending.");}
}